const queryClient = new QueryClient();
const InventoryContext = createContext<ReturnType<typeof makeInventory> | null>(null);

function makeInventory() {
  const [products, setProducts] = useState<Product[]>(() => readStore('keystone-products', seedProducts));
  const [history, setHistory] = useState<StockEntry[]>(() => readStore('keystone-history', seedProducts.slice(0, 8).map((p, i) => ({ id:`seed-${i}`, productId:p.id, productName:p.name, type:'PURCHASE' as const, quantity:p.quantity, note:'Opening stock', date:p.createdAt }))));
  const [purchases, setPurchases] = useState<Purchase[]>(() => readStore('keystone-purchases', []));
  const [sales, setSales] = useState<Sale[]>(() => readStore('keystone-sales', []));
  useEffect(() => writeStore('keystone-products', products), [products]);
  useEffect(() => writeStore('keystone-history', history), [history]);
  useEffect(() => writeStore('keystone-purchases', purchases), [purchases]);
  useEffect(() => writeStore('keystone-sales', sales), [sales]);
  const adjustStock = (productId: string, amount: number, type: StockEntry['type'], note: string) => {
    const product = products.find(p => p.id === productId); if (!product || amount === 0) return false;
    if (product.quantity + amount < 0) return false;
    setProducts(prev => prev.map(p => p.id === productId ? { ...p, quantity: p.quantity + amount } : p));
    setHistory(prev => [{ id:`h-${Date.now()}`, productId, productName:product.name, type, quantity:Math.abs(amount), note, date:new Date().toISOString() }, ...prev]);
    return true;
  };
  const saveProduct = (data: Omit<Product, 'id'|'createdAt'>, id?: string) => {
    if (id) setProducts(prev => prev.map(p => p.id === id ? { ...p, ...data } : p));
    else setProducts(prev => [{ ...data, id:`p-${Date.now()}`, createdAt:new Date().toISOString() }, ...prev]);
  };
  const addPurchase = (data: Omit<Purchase, 'id'|'total'>) => {
    const total = data.quantity * data.purchasePrice;
    setPurchases(prev => [{ ...data, id:`pur-${Date.now()}`, total }, ...prev]);
    adjustStock(data.productId, data.quantity, 'PURCHASE', `Invoice ${data.invoice}`);
  };
  const addSale = (sale: Omit<Sale, 'id'|'date'>) => {
    if (sale.items.some(item => (products.find(p => p.id === item.productId)?.quantity ?? 0) < item.quantity)) return false;
    setSales(prev => [{ ...sale, id:`sale-${Date.now()}`, date:new Date().toISOString() }, ...prev]);
    sale.items.forEach(item => adjustStock(item.productId, -item.quantity, 'SALE', `POS sale · ${sale.payment}`));
    return true;
  };
  return { products, history, purchases, sales, saveProduct, addPurchase, addSale, adjustStock };
}
function InventoryProvider({ children }: { children: ReactNode }) {
  const value = makeInventory();
  return <InventoryContext.Provider value={value}>{children}</InventoryContext.Provider>;
}
function useInventory() { const ctx = useContext(InventoryContext); if (!ctx) throw new Error('Inventory provider missing'); return ctx; }

const inputClass = 'h-11 w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--card))] px-3.5 text-sm outline-none transition focus:border-[hsl(var(--secondary))] focus:ring-2 focus:ring-[hsl(var(--secondary)/.2)]';
const buttonPrimary = 'inline-flex items-center justify-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 py-2.5 text-sm font-semibold text-[hsl(var(--primary-foreground))] transition hover:-translate-y-0.5 hover:shadow-lg';
