function InventoryPage() {
  const { products } = useInventory(); const [location, setLocation] = useLocation(); const params = new URLSearchParams(location.split('?')[1] || '');
  const [search, setSearch] = useState(''); const [category, setCategory] = useState(params.get('category') || ''); const [brand, setBrand] = useState(''); const [status, setStatus] = useState(params.get('status') || ''); const [sort, setSort] = useState('newest');
  const filtered = useMemo(() => products.filter(p => (!search || `${p.name} ${p.brand} ${p.sku} ${p.model}`.toLowerCase().includes(search.toLowerCase())) && (!category || p.category === category) && (!brand || p.brand === brand) && (!status || statusOf(p) === status)).sort((a,b) => sort === 'price' ? b.sellingPrice-a.sellingPrice : sort === 'stock' ? a.quantity-b.quantity : b.createdAt.localeCompare(a.createdAt)), [products,search,category,brand,status,sort]);
   return <div className="fade-up"><PageTitle kicker={`Catalog / ${products.length} products`} title="Inventory" description="A considered view of every product on your shelves." action={<Link href="/inventory/new" data-testid="button-add-product" className={buttonPrimary}><Plus className="h-4 w-4" /> Add product</Link>} />
    <div className="mb-5 grid gap-3 lg:grid-cols-[1.5fr_1fr_1fr_1fr_1fr]"><SearchField value={search} onChange={setSearch} />{[['category',category,setCategory,categories],['brand',brand,setBrand,brands],['status',status,setStatus,['IN STOCK','LOW STOCK','OUT OF STOCK']]].map(([name,value,setter,options]) => <select key={name as string} aria-label={`Filter by ${name}`} data-testid={`select-filter-${name}`} className={inputClass} value={value as string} onChange={e => (setter as (v:string)=>void)(e.target.value)}><option value="">{`All ${name}s`}</option>{(options as string[]).map(option => <option key={option} value={option}>{option}</option>)}</select>)}<select aria-label="Sort inventory" data-testid="select-sort-inventory" className={inputClass} value={sort} onChange={e => setSort(e.target.value)}><option value="newest">Newest first</option><option value="price">Price: high to low</option><option value="stock">Stock: low to high</option></select></div>
    <div className="mb-6 flex items-center justify-between"><p className="text-sm text-[hsl(var(--muted-foreground))]"><strong className="text-[hsl(var(--foreground))]">{filtered.length}</strong> products showing</p><button className={buttonQuiet} onClick={() => { setSearch(''); setCategory(''); setBrand(''); setStatus(''); }} data-testid="button-clear-filters"><SlidersHorizontal className="h-4 w-4" /> Clear filters</button></div>
    {filtered.length ? <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">{filtered.map(p => <ProductCard key={p.id} product={p} />)}</div> : <EmptyState icon={Filter} title="Nothing matches those filters" description="Try a different search or clear the filters to see your catalog." />}</div>;
}

function StockModal({ product, mode, onClose }: { product: Product; mode:'add'|'sell'; onClose:()=>void }) {
  const { adjustStock } = useInventory(); const [quantity, setQuantity] = useState(1); const [done, setDone] = useState(false); const isAdd = mode === 'add';
  const submit = () => { if (adjustStock(product.id, isAdd ? quantity : -quantity, isAdd ? 'PURCHASE' : 'SALE', isAdd ? 'Manual stock received' : 'Quick sale')) setDone(true); };
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-[hsl(215_28%_18%/.35)] p-4"><div className="w-full max-w-sm rounded-3xl bg-[hsl(var(--card))] p-6 shadow-2xl"><div className="flex items-start justify-between"><div><p className={pageKicker}>{isAdd ? 'Stock received' : 'Quick sale'}</p><h2 className="mt-1 text-xl font-bold">{product.name}</h2></div><button onClick={onClose} data-testid="button-close-stock-modal"><X className="h-5 w-5" /></button></div>{done ? <div className="py-8 text-center"><span className="mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-[hsl(var(--accent))]"><Check className="h-6 w-6" /></span><p className="mt-4 font-semibold">Stock updated</p><button className={`${buttonPrimary} mt-5`} onClick={onClose} data-testid="button-done-stock-modal">Done</button></div> : <><label className="mt-7 block text-xs font-semibold">Quantity<input type="number" min="1" max={isAdd ? undefined : product.quantity} className={`${inputClass} mt-2`} value={quantity} onChange={e => setQuantity(Math.max(1,Number(e.target.value)))} data-testid="input-stock-quantity" /></label><div className="mt-6 flex gap-2"><button className={`${buttonQuiet} flex-1`} onClick={onClose}>Cancel</button><button className={`${buttonPrimary} flex-1`} onClick={submit} data-testid={`button-confirm-${mode}-stock`}>{isAdd ? 'Add stock' : 'Record sale'}</button></div></>}</div></div>;
}
