  return <div className="fade-up"><PageTitle kicker="Manage / Ledger" title="Stock history" description="Every movement, in one calm and reliable trail." action={<div className="flex gap-2">{['ALL','PURCHASE','SALE'].map(v => <button key={v} onClick={() => setFilter(v)} data-testid={`button-history-${v.toLowerCase()}`} className={`rounded-full px-3 py-2 text-[10px] font-bold tracking-wider ${filter === v ? 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'border border-[hsl(var(--border))] bg-[hsl(var(--card))]'}`}>{v}</button>)}</div>} /><div className="overflow-hidden rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]"><div className="hidden grid-cols-[1.2fr_1fr_.7fr_1.6fr_1fr] border-b border-[hsl(var(--border))] px-5 py-3 font-mono text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))] sm:grid"><span>Product</span><span>Movement</span><span>Qty</span><span>Note</span><span>Date</span></div>{rows.map(row => <div key={row.id} className="grid gap-1 border-b border-[hsl(var(--border))] px-5 py-4 last:border-0 sm:grid-cols-[1.2fr_1fr_.7fr_1.6fr_1fr] sm:items-center"><span className="text-sm font-semibold">{row.productName}</span><span className={`text-xs font-bold ${row.type === 'SALE' ? 'text-[hsl(var(--destructive))]' : 'text-[hsl(var(--accent-foreground))]'}`}>{row.type}</span><span className="font-mono text-sm">{row.type === 'SALE' ? '-' : '+'}{row.quantity}</span><span className="text-xs text-[hsl(var(--muted-foreground))]">{row.note}</span><span className="text-xs text-[hsl(var(--muted-foreground))]">{dateLabel(row.date)}</span></div>)}</div></div>;
