function PurchasesPage() {
  const { purchases } = useInventory(); return <div className="fade-up"><PageTitle kicker="Flow / Incoming" title="Purchases" description="Restock the catalog and keep your incoming goods visible." action={<Link href="/purchases/new" className={buttonPrimary} data-testid="button-new-purchase"><Plus className="h-4 w-4" /> New purchase</Link>} />{purchases.length ? <div className="overflow-hidden rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]"><div className="hidden grid-cols-[1.2fr_1fr_1fr_.8fr_1fr] border-b border-[hsl(var(--border))] px-5 py-3 font-mono text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))] sm:grid"><span>Product</span><span>Supplier</span><span>Invoice</span><span>Qty</span><span>Total</span></div>{purchases.map(p => <div key={p.id} className="grid gap-1 border-b border-[hsl(var(--border))] px-5 py-4 last:border-0 sm:grid-cols-[1.2fr_1fr_1fr_.8fr_1fr] sm:items-center"><span><strong className="block text-sm">{p.productName}</strong><small className="text-xs text-[hsl(var(--muted-foreground))]">{dateLabel(p.date)}</small></span><span className="text-sm">{p.supplier}</span><span className="font-mono text-xs">{p.invoice}</span><span className="text-sm">{p.quantity}</span><span className="font-semibold">{money(p.total)}</span></div>)}</div> : <EmptyState icon={Truck} title="No purchases yet" description="Record your next delivery and inventory will increase automatically." />}</div>;
}
function PurchaseFormPage() {
  const { products, addPurchase } = useInventory(); const [, setLocation] = useLocation(); const [productId, setProductId] = useState(products[0]?.id || ''); const product = products.find(p => p.id === productId); const [form, setForm] = useState({ supplier:'', invoice:'', date:new Date().toISOString().slice(0,10), quantity:'1', purchasePrice:String(product?.purchasePrice || '') });
  const choose = (id:string) => { setProductId(id); const p = products.find(x => x.id === id); if (p) setForm(f => ({ ...f, purchasePrice:String(p.purchasePrice) })); };
  const submit = (e:FormEvent) => { e.preventDefault(); if (!product) return; addPurchase({ supplier:form.supplier, invoice:form.invoice, date:form.date, productId, productName:product.name, quantity:Number(form.quantity), purchasePrice:Number(form.purchasePrice) }); setLocation('/purchases'); };
  return <div className="fade-up"><Link href="/purchases" className="mb-7 inline-flex items-center gap-2 text-xs font-semibold text-[hsl(var(--muted-foreground))]" data-testid="link-back-purchases"><ArrowLeft className="h-4 w-4" /> Back to purchases</Link><PageTitle kicker="Flow / Incoming" title="New purchase" description="One entry adds the delivery to your ledger and your shelf." /><form onSubmit={submit} className="max-w-2xl rounded-3xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 sm:p-8"><div className="grid gap-5 sm:grid-cols-2"><label className="text-xs font-semibold">Supplier<input required className={`${inputClass} mt-2`} value={form.supplier} onChange={e => setForm({...form,supplier:e.target.value})} placeholder="Supplier name" data-testid="input-purchase-supplier" /></label><label className="text-xs font-semibold">Invoice number<input required className={`${inputClass} mt-2 font-mono`} value={form.invoice} onChange={e => setForm({...form,invoice:e.target.value})} placeholder="INV-2024-014" data-testid="input-purchase-invoice" /></label><label className="text-xs font-semibold">Date<input required type="date" className={`${inputClass} mt-2`} value={form.date} onChange={e => setForm({...form,date:e.target.value})} data-testid="input-purchase-date" /></label><label className="text-xs font-semibold">Product<select className={`${inputClass} mt-2`} value={productId} onChange={e => choose(e.target.value)} data-testid="select-purchase-product">{products.map(p => <option key={p.id} value={p.id}>{p.name} · {p.sku}</option>)}</select></label><label className="text-xs font-semibold">Quantity<input required min="1" type="number" className={`${inputClass} mt-2`} value={form.quantity} onChange={e => setForm({...form,quantity:e.target.value})} data-testid="input-purchase-quantity" /></label><label className="text-xs font-semibold">Purchase price<input required min="0" type="number" className={`${inputClass} mt-2`} value={form.purchasePrice} onChange={e => setForm({...form,purchasePrice:e.target.value})} data-testid="input-purchase-price" /></label></div><div className="mt-7 flex items-center justify-between rounded-2xl bg-[hsl(var(--accent)/.55)] p-4"><div><p className="text-xs text-[hsl(var(--muted-foreground))]">Purchase total</p><p className="mt-1 text-xl font-bold">{money(Number(form.quantity || 0) * Number(form.purchasePrice || 0))}</p></div><button className={buttonPrimary} type="submit" data-testid="button-save-purchase"><Check className="h-4 w-4" /> Save purchase</button></div></form></div>;
}

function SalesPage() {
  const { products, addSale } = useInventory(); const [search, setSearch] = useState(''); const [cart, setCart] = useState<{ productId:string; quantity:number }[]>([]); const [discount, setDiscount] = useState('0'); const [payment, setPayment] = useState('Cash'); const [complete, setComplete] = useState(false);
  const results = products.filter(p => p.quantity > 0 && `${p.name} ${p.brand} ${p.sku}`.toLowerCase().includes(search.toLowerCase())).slice(0,6);
  const items = cart.map(i => ({ ...i, product:products.find(p => p.id === i.productId)! })).filter(i => i.product);
  const subtotal = items.reduce((sum,i) => sum + i.product.sellingPrice*i.quantity,0); const total = Math.max(0, subtotal - Number(discount || 0));
  const add = (p:Product) => setCart(prev => prev.some(i => i.productId === p.id) ? prev.map(i => i.productId === p.id ? {...i,quantity:Math.min(p.quantity,i.quantity+1)} : i) : [...prev,{productId:p.id,quantity:1}]);
  const finish = () => { if (!items.length) return; const ok = addSale({ items:items.map(i => ({ productId:i.productId, productName:i.product.name, quantity:i.quantity, price:i.product.sellingPrice })), subtotal, discount:Number(discount || 0), total, payment }); if (ok) { setComplete(true); setCart([]); setDiscount('0'); } };
  return <div className="fade-up"><PageTitle kicker="Flow / Point of sale" title="Sales" description="A focused checkout for the counter, without the noise." action={<div className="rounded-full bg-[hsl(var(--accent))] px-4 py-2 text-xs font-semibold"><span className="mr-1 font-mono">{cart.reduce((s,i) => s+i.quantity,0)}</span> items in cart</div>} />{complete && <div className="mb-5 flex items-center justify-between rounded-2xl bg-[hsl(var(--accent))] px-4 py-3 text-sm font-semibold" data-testid="status-sale-complete"><span className="flex items-center gap-2"><Check className="h-4 w-4" /> Sale completed and stock updated.</span><button onClick={() => setComplete(false)}><X className="h-4 w-4" /></button></div>}<div className="grid gap-6 lg:grid-cols-[1.25fr_.75fr]"><section className="rounded-3xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 sm:p-7"><div className="mb-6 flex items-center justify-between"><div><p className={pageKicker}>Select items</p><h2 className="mt-1 text-xl font-bold">Product shelf</h2></div><div className="w-56"><SearchField value={search} onChange={setSearch} placeholder="Search shelf" /></div></div><div className="grid gap-3 sm:grid-cols-2">{results.map(p => <button key={p.id} onClick={() => add(p)} data-testid={`button-add-cart-${p.id}`} className="flex items-center gap-3 rounded-2xl border border-[hsl(var(--border))] p-3 text-left transition hover:-translate-y-0.5 hover:border-[hsl(var(--secondary))] hover:shadow-md"><ProductImage product={p} className="h-16 w-16 shrink-0 rounded-xl" /><span className="min-w-0 flex-1"><strong className="block truncate text-sm">{p.name}</strong><small className="mt-1 block text-xs text-[hsl(var(--muted-foreground))]">{money(p.sellingPrice)} · {p.quantity} available</small></span><Plus className="h-4 w-4" /></button>)}</div></section><aside className="rounded-3xl bg-[hsl(var(--primary))] p-5 text-[hsl(var(--primary-foreground))] sm:p-7"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-[hsl(var(--primary-foreground)/.55)]">Current sale</p><h2 className="mt-1 text-xl font-bold">Cart</h2></div><ShoppingCart className="h-5 w-5 text-[hsl(var(--secondary))]" /></div><div className="mt-6 min-h-40 space-y-3">{items.length ? items.map(i => <div key={i.productId} className="flex items-center gap-2"><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{i.product.name}</p><p className="text-xs text-[hsl(var(--primary-foreground)/.55)]">{money(i.product.sellingPrice)} each</p></div><div className="flex items-center gap-2 rounded-lg bg-[hsl(var(--primary-foreground)/.1)] p-1"><button onClick={() => setCart(c => c.map(x => x.productId === i.productId ? {...x,quantity:x.quantity-1} : x).filter(x => x.quantity > 0))} data-testid={`button-decrease-cart-${i.productId}`}><Minus className="h-3 w-3" /></button><span className="w-4 text-center text-xs">{i.quantity}</span><button onClick={() => add(i.product)} data-testid={`button-increase-cart-${i.productId}`}><Plus className="h-3 w-3" /></button></div></div>) : <p className="py-12 text-center text-sm text-[hsl(var(--primary-foreground)/.5)]">Add a product to begin.</p>}</div><div className="border-t border-[hsl(var(--primary-foreground)/.14)] pt-5"><div className="flex items-center justify-between text-sm text-[hsl(var(--primary-foreground)/.62)]"><span>Subtotal</span><span>{money(subtotal)}</span></div><label className="mt-3 flex items-center justify-between text-sm text-[hsl(var(--primary-foreground)/.62)]">Discount<input type="number" min="0" className="ml-4 h-8 w-24 rounded-lg border-0 bg-[hsl(var(--primary-foreground)/.1)] px-2 text-right text-sm text-[hsl(var(--primary-foreground))] outline-none" value={discount} onChange={e => setDiscount(e.target.value)} data-testid="input-sale-discount" /></label><div className="mt-5 flex items-end justify-between"><span className="text-sm text-[hsl(var(--primary-foreground)/.62)]">Total</span><strong className="text-3xl tracking-[-.05em]">{money(total)}</strong></div><p className="mt-6 font-mono text-[10px] uppercase tracking-wider text-[hsl(var(--primary-foreground)/.5)]">Payment method</p><div className="mt-2 grid grid-cols-4 gap-1.5">{['Cash','UPI','Card','Credit'].map(method => <button key={method} onClick={() => setPayment(method)} data-testid={`button-payment-${method.toLowerCase()}`} className={`rounded-lg px-1 py-2 text-[10px] font-semibold ${payment === method ? 'bg-[hsl(var(--secondary))] text-[hsl(var(--secondary-foreground))]' : 'bg-[hsl(var(--primary-foreground)/.1)]'}`}>{method}</button>)}</div><button disabled={!items.length} onClick={finish} data-testid="button-complete-sale" className="mt-4 flex w-full items-center justify-center gap-2 rounded-xl bg-[hsl(var(--secondary))] px-4 py-3 text-sm font-bold text-[hsl(var(--secondary-foreground))] transition hover:-translate-y-0.5 disabled:cursor-not-allowed disabled:opacity-40"><Check className="h-4 w-4" /> Complete sale</button></div></aside></div></div>;
}

 function Router() {
   return <InventoryProvider><InventoryShell><ErrorBoundary><Switch><Route path="/" component={HomePage} /><Route path="/inventory" component={InventoryPage} /><Route path="/inventory/new" component={ProductFormPage} /><Route path="/inventory/:id/edit" component={ProductFormPage} /><Route path="/product/:id" component={ProductDetailScreen} /><Route path="/stock-history" component={HistoryPage} /><Route path="/purchases" component={PurchasesPage} /><Route path="/purchases/new" component={PurchaseFormPage} /><Route path="/sales" component={SalesPage} /><Route component={NotFound} /></Switch></ErrorBoundary></InventoryShell></InventoryProvider>;
 }
function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}
export default App;